import { clearSession, readStoredToken } from "../auth/session";

export class ApiError extends Error {
  status: number;
  statusText: string;
  body: unknown;

  constructor(status: number, statusText: string, body: unknown) {
    super(`${status} ${statusText}`);
    this.name = "ApiError";
    this.status = status;
    this.statusText = statusText;
    this.body = body;
  }
}

export interface RequestOpts {
  headers?: Record<string, string>;
}

async function request<T>(path: string, options?: RequestInit): Promise<T> {
  const url = `/api${path}`;
  const token = readStoredToken();
  // FormData bodies set their own multipart Content-Type (with the boundary).
  const headers: Record<string, string> = {
    ...(options?.body instanceof FormData ? {} : { "Content-Type": "application/json" }),
    ...(options?.headers as Record<string, string>),
  };
  if (token) {
    headers["Authorization"] = `Bearer ${token}`;
  }

  const response = await fetch(url, {
    ...options,
    headers,
  });

  if (!response.ok) {
    if (response.status === 401) {
      if (typeof window !== "undefined") {
        clearSession();
        if (window.location.pathname !== "/login") {
          const returnTo = window.location.pathname + window.location.search;
          window.location.href = `/login?returnTo=${encodeURIComponent(returnTo)}`;
        }
      }
    }
    let body: unknown;
    try {
      body = await response.json();
    } catch {
      body = await response.text();
    }
    throw new ApiError(response.status, response.statusText, body);
  }

  if (response.status === 204) {
    return undefined as T;
  }

  return response.json() as Promise<T>;
}

function mergeHeaders(opts?: RequestOpts): RequestInit | undefined {
  if (!opts?.headers) return undefined;
  // Bearer token wins on collision: strip any caller-supplied Authorization.
  const filtered: Record<string, string> = {};
  for (const [key, value] of Object.entries(opts.headers)) {
    if (key.toLowerCase() === "authorization") continue;
    filtered[key] = value;
  }
  return { headers: filtered };
}

export const api = {
  get<T>(path: string, _body?: undefined, opts?: RequestOpts): Promise<T> {
    return request<T>(path, mergeHeaders(opts));
  },

  post<T>(path: string, body: unknown, opts?: RequestOpts): Promise<T> {
    return request<T>(path, {
      method: "POST",
      body: JSON.stringify(body),
      ...mergeHeaders(opts),
    });
  },

  put<T>(path: string, body: unknown, opts?: RequestOpts): Promise<T> {
    return request<T>(path, {
      method: "PUT",
      body: JSON.stringify(body),
      ...mergeHeaders(opts),
    });
  },

  patch<T>(path: string, body: unknown, opts?: RequestOpts): Promise<T> {
    return request<T>(path, {
      method: "PATCH",
      body: JSON.stringify(body),
      ...mergeHeaders(opts),
    });
  },

  /** Multipart POST (file uploads). */
  upload<T>(path: string, body: FormData, opts?: RequestOpts): Promise<T> {
    return request<T>(path, { method: "POST", body, ...mergeHeaders(opts) });
  },

  delete<T>(path: string, _body?: undefined, opts?: RequestOpts): Promise<T> {
    return request<T>(path, { method: "DELETE", ...mergeHeaders(opts) });
  },
};

import { createContext, useCallback, useContext, useEffect, useLayoutEffect, useMemo, useRef, useState } from "react";
import type { ReactNode } from "react";
import { getMyProfile } from "../api/people";
import { useRouterRefresh } from "../routing/navigation";
import { clearSession, decodeJwtPayload, reconcileSession, setSession } from "./session";

export interface RegisterPayload {
  role: "GUEST" | "ORGANIZER";
  email: string;
  password: string;
}

export interface RegisterResult {
  partyId: string;
  role: string;
}

interface AuthContextValue {
  token: string | null;
  username: string | null;
  displayName: string | null;
  permissions: string[];
  /** Set by `register()` for the lifetime of the current session — lets
   * `/onboarding` pick the right `Step[]` config right after a fresh
   * registration without a follow-up `GET /api/people/me` call. `null`
   * when the app was loaded from a stored token instead (returning user),
   * in which case callers fall back to a profile/leaderships lookup. */
  registeredRole: RegisterResult | null;
  login: (email: string, password: string) => Promise<void>;
  register: (payload: RegisterPayload) => Promise<RegisterResult>;
  /** Stores `jwt` as the session (`auth/session.ts`), decodes its claims, and updates
   * context state — identical body to the internal `applyToken`, just
   * exposed publicly for a non-login/register auth event (spec.md §4's
   * account-merge flow: the visitor is authenticated by a merge response,
   * not a `/api/auth/login` or `/api/auth/register` call). */
  applyExternalToken: (jwt: string) => void;
  logout: () => void;
  /** Clears an expired session without leaving the page (`AuthGuard`). */
  expireSession: () => void;
}

const AuthContext = createContext<AuthContextValue | null>(null);

function claimsOf(token: string | null): { username: string | null; permissions: string[] } {
  if (!token) return { username: null, permissions: [] };
  const payload = decodeJwtPayload(token);
  return { username: payload.sub ?? null, permissions: payload.permissions ?? [] };
}

/** `initialToken` seeds the first render (the server cookie under Next, the
 * localStorage token under Vite); a mount effect then reconciles it with the
 * browser's stored session. */
export function AuthProvider({ children, initialToken }: { children: ReactNode; initialToken: string | null }) {
  const [token, setToken] = useState<string | null>(initialToken);
  const [username, setUsername] = useState<string | null>(() => claimsOf(initialToken).username);
  const [permissions, setPermissions] = useState<string[]>(() => claimsOf(initialToken).permissions);
  const [displayName, setDisplayName] = useState<string | null>(null);
  const [registeredRole, setRegisteredRole] = useState<RegisterResult | null>(null);

  const refreshDisplayName = useCallback(async () => {
    try {
      const me = await getMyProfile();
      setDisplayName(me.display_name);
    } catch {
      setDisplayName(null);
    }
  }, []);

  const showToken = useCallback((jwt: string | null) => {
    const claims = claimsOf(jwt);
    setToken(jwt);
    setUsername(claims.username);
    setPermissions(claims.permissions);
  }, []);

  const resetAuth = useCallback(() => {
    clearSession();
    showToken(null);
    setDisplayName(null);
    setRegisteredRole(null);
  }, [showToken]);

  const applyToken = useCallback(
    (jwt: string) => {
      setSession(jwt);
      showToken(jwt);
      void refreshDisplayName();
    },
    [showToken, refreshDisplayName],
  );

  // Layout effect: runs before any child's data fetch reads the stored token.
  useLayoutEffect(() => {
    const reconciled = reconcileSession();
    if (reconciled !== initialToken) showToken(reconciled);
    if (reconciled) void refreshDisplayName();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  const refreshRouter = useRouterRefresh();
  const previousToken = useRef(token);
  useEffect(() => {
    if (previousToken.current === token) return;
    previousToken.current = token;
    refreshRouter();
  }, [token, refreshRouter]);

  const login = useCallback(
    async (email: string, password: string) => {
      const response = await fetch("/api/auth/login", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ email, password }),
      });

      if (!response.ok) {
        const body = await response.json().catch(() => ({ message: "Login failed" }));
        throw new Error(body.message ?? "Login failed");
      }

      const { token: jwt } = await response.json();
      applyToken(jwt);
    },
    [applyToken],
  );

  const register = useCallback(
    async (payload: RegisterPayload): Promise<RegisterResult> => {
      const response = await fetch("/api/auth/register", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          role: payload.role,
          email: payload.email,
          password: payload.password,
        }),
      });

      if (!response.ok) {
        const body = await response.json().catch(() => ({ message: "Registration failed" }));
        throw new Error(body.message ?? "Registration failed");
      }

      const { token: jwt, party_id: partyId, role } = await response.json();
      applyToken(jwt);
      const result = { partyId, role };
      setRegisteredRole(result);
      return result;
    },
    [applyToken],
  );

  const logout = useCallback(() => {
    resetAuth();
    window.location.href = "/login";
  }, [resetAuth]);

  const value = useMemo<AuthContextValue>(
    () => ({
      token,
      username,
      displayName,
      permissions,
      registeredRole,
      login,
      register,
      applyExternalToken: applyToken,
      logout,
      expireSession: resetAuth,
    }),
    [token, username, displayName, permissions, registeredRole, login, register, applyToken, logout, resetAuth],
  );

  return <AuthContext value={value}>{children}</AuthContext>;
}

export function useAuth(): AuthContextValue {
  const context = useContext(AuthContext);
  if (!context) {
    throw new Error("useAuth must be used within an AuthProvider");
  }
  return context;
}

import {
  useEffect,
  useId,
  useMemo,
  useRef,
  useState,
  type KeyboardEvent,
  type ReactNode,
  type SyntheticEvent,
} from "react";
import { createPortal } from "react-dom";
import type { Category } from "../../api/categories";
import { useCategories } from "../../hooks/useCategories";
import {
  CATEGORY_PATH_SEPARATOR,
  buildCategoryIndex,
  categoryPathNames,
  foldCategoryText,
  isLeaf,
  searchCategories,
  type CategoryIndex,
} from "../../utils/categoryTree";
import { pluralPl } from "../../utils/plural";
import { INPUT_CLASS } from "./appComponents";
import { SearchIcon } from "./appIcons";
import { ModalSheet } from "./ModalSheet";

/** `leaf`: only leaves select (items, needed items). `any`: every node selects (admin parent). */
export type CategoryPickerMode = "leaf" | "any";

export interface CategoryTreePickerProps {
  /** Id of the host's visible label `<span>`; the trigger is never wrapped in a `<label>`. */
  labelledBy: string;
  /** Selected category id; `null` or `""` means none. */
  value: string | null;
  /** Receives the chosen id, or `null` from "Kategoria główna (brak)". */
  onChange: (id: string | null) => void;
  mode?: CategoryPickerMode;
  /** `any` mode only: offer "Kategoria główna (brak)", which clears the value. */
  allowRoot?: boolean;
  placeholder?: string;
  disabled?: boolean;
  id?: string;
  "aria-invalid"?: boolean;
  "aria-describedby"?: string;
}

const SHEET_TITLE = "Wybierz kategorię";
const MAX_RESULTS = 50;
const ROOT_LABEL = "Kategoria główna (brak)";
const CHEVRON = "›";

const TEXT_BTN_CLASS = "rounded-md font-bold text-ink-soft hover:text-ink";
const ROW_CLASS =
  "flex w-full items-center justify-between gap-3 border-b border-line px-1 py-3 text-left text-[14.5px] text-ink hover:bg-cream";

/** The picker's sheet events must not reach a host handler (a form's Enter/Esc, an outer sheet's Tab trap). */
function stop(event: SyntheticEvent) {
  event.stopPropagation();
}

/**
 * Category field: a trigger button plus a portaled search + drill-down sheet.
 * The trigger subscribes to `useCategories` once and hands the index to the
 * sheet, so opening it never refetches.
 */
export function CategoryTreePicker({
  labelledBy,
  value,
  onChange,
  mode = "leaf",
  allowRoot = false,
  placeholder = SHEET_TITLE,
  disabled = false,
  id,
  "aria-invalid": ariaInvalid,
  "aria-describedby": ariaDescribedBy,
}: CategoryTreePickerProps) {
  const generatedId = useId();
  const triggerId = id ?? `${generatedId}-trigger`;
  const { data, loading, error } = useCategories();
  const index = useMemo(() => buildCategoryIndex(data), [data]);
  const [open, setOpen] = useState(false);

  const selected = value ? index.byId.get(value) : undefined;
  const ancestors = selected ? categoryPathNames(index, selected.id).slice(0, -1) : [];

  function select(next: string | null) {
    setOpen(false);
    onChange(next);
  }

  return (
    <>
      <button
        type="button"
        id={triggerId}
        aria-labelledby={`${labelledBy} ${triggerId}`}
        aria-haspopup="dialog"
        aria-invalid={ariaInvalid || undefined}
        aria-describedby={ariaDescribedBy}
        disabled={disabled}
        onClick={() => setOpen(true)}
        className={`${INPUT_CLASS} flex w-full items-center justify-between gap-2 text-left aria-[invalid=true]:border-danger disabled:opacity-60`}
      >
        {selected ? (
          <span className="min-w-0">
            {ancestors.length > 0 && (
              <>
                <span className="block text-[12px] text-ink-soft">
                  {ancestors.join(CATEGORY_PATH_SEPARATOR)} {CHEVRON}
                </span>{" "}
              </>
            )}
            <span className="block font-bold">{selected.name}</span>
          </span>
        ) : (
          <span className="text-ink-soft">{placeholder}</span>
        )}
        <span aria-hidden="true" className="text-base text-ink-soft">
          {CHEVRON}
        </span>
      </button>
      {open && (
        // Portaled out of the host <form>/<label>; React events still bubble, so the wrapper stops them.
        <span className="contents" onClick={stop} onKeyDown={stop}>
          {createPortal(
            <CategoryTreeSheet
              idPrefix={generatedId}
              index={index}
              loading={loading}
              error={error}
              value={value || null}
              mode={mode}
              allowRoot={mode === "any" && allowRoot}
              onSelect={select}
              onClose={() => setOpen(false)}
            />,
            document.body,
          )}
        </span>
      )}
    </>
  );
}

function CategoryTreeSheet({
  idPrefix,
  index,
  loading,
  error,
  value,
  mode,
  allowRoot,
  onSelect,
  onClose,
}: {
  idPrefix: string;
  index: CategoryIndex;
  loading: boolean;
  error: string | null;
  value: string | null;
  mode: CategoryPickerMode;
  allowRoot: boolean;
  onSelect: (id: string | null) => void;
  onClose: () => void;
}) {
  // `undefined` until the user navigates: the selected node's parent level, even if the tree loads after opening.
  const [chosenLevel, setLevel] = useState<string | null | undefined>(undefined);
  const level = chosenLevel !== undefined ? chosenLevel : value ? (index.byId.get(value)?.parent_id ?? null) : null;
  const [query, setQuery] = useState("");
  const [active, setActive] = useState(-1);
  const listRef = useRef<HTMLUListElement>(null);
  const focusFirstRow = useRef(false);
  const listboxId = `${idPrefix}-results`;
  const optionId = (i: number) => `${idPrefix}-result-${i}`;

  const needle = foldCategoryText(query.trim());
  const search = useMemo(() => searchCategories(index, query), [index, query]);
  const searching = needle !== "";
  const shown = search.results.slice(0, MAX_RESULTS);
  const showResults = searching && shown.length > 0;

  const current = level ? index.byId.get(level) : undefined;
  const crumbs = current ? categoryPathNames(index, current.id) : [];
  const rows = index.childrenOf(current?.id ?? null);

  useEffect(() => {
    if (!focusFirstRow.current) return;
    focusFirstRow.current = false;
    listRef.current?.querySelector<HTMLButtonElement>("button")?.focus();
  }, [level]);

  function goTo(next: string | null) {
    focusFirstRow.current = true;
    setLevel(next);
  }

  /** Ancestor id `depth` levels below the root on the current path. */
  function ancestorAt(depth: number): string | null {
    let node = current;
    for (let i = crumbs.length - 1; i > depth && node; i--) {
      node = node.parent_id ? index.byId.get(node.parent_id) : undefined;
    }
    return node?.id ?? null;
  }

  function changeQuery(next: string) {
    setQuery(next);
    setActive(-1);
  }

  function chooseResult(category: Category) {
    if (mode === "leaf" && !isLeaf(index, category.id)) {
      changeQuery("");
      setLevel(category.id);
      return;
    }
    onSelect(category.id);
  }

  function handleSearchKeyDown(event: KeyboardEvent<HTMLInputElement>) {
    if (event.key === "Escape") {
      if (query === "") return;
      // Clear only the search; the sheet must not see this Esc.
      event.preventDefault();
      event.stopPropagation();
      changeQuery("");
      return;
    }
    if (event.key === "ArrowDown" || event.key === "ArrowUp") {
      const count = shown.length;
      if (!showResults) return;
      event.preventDefault();
      const step = event.key === "ArrowDown" ? 1 : -1;
      setActive((i) => (i < 0 ? (step > 0 ? 0 : count - 1) : (i + step + count) % count));
      return;
    }
    if (event.key === "Enter") {
      // Never an implicit form submission.
      event.preventDefault();
      if (showResults && active >= 0 && active < shown.length) chooseResult(shown[active].category);
    }
  }

  return (
    <ModalSheet title={SHEET_TITLE} onClose={onClose}>
      <label className="flex items-center gap-2 rounded-xl border-[1.5px] border-line bg-cream px-3 py-2.5 focus-within:border-mint">
        <SearchIcon c="currentColor" />
        <input
          role="combobox"
          aria-label="Szukaj kategorii"
          aria-autocomplete="list"
          aria-expanded={showResults}
          aria-controls={showResults ? listboxId : undefined}
          aria-activedescendant={showResults && active >= 0 ? optionId(active) : undefined}
          placeholder="Szukaj kategorii, np. „buty”"
          value={query}
          onChange={(e) => changeQuery(e.target.value)}
          onKeyDown={handleSearchKeyDown}
          className="min-w-0 flex-1 bg-transparent text-[14px] text-ink outline-none placeholder:text-ink-soft"
        />
      </label>

      {error && (
        <p role="alert" className="mt-3 text-[12.5px] font-semibold text-danger">
          {error}
        </p>
      )}
      {loading && <p className="mt-3 text-[13px] text-ink-soft">Ładowanie kategorii…</p>}

      {searching ? (
        <>
          <p aria-live="polite" className="mb-0.5 mt-2.5 text-[12px] text-ink-soft">
            {search.total} {pluralPl(search.total, "wynik", "wyniki", "wyników")}
          </p>
          {search.total > MAX_RESULTS && (
            <p className="text-[12px] text-ink-soft">
              Pokazano {MAX_RESULTS} z {search.total} — zawęź wyszukiwanie
            </p>
          )}
          {showResults && (
            <ul id={listboxId} role="listbox" aria-label="Wyniki wyszukiwania" className="flex flex-col">
              {shown.map(({ category, path }, i) => (
                <li
                  key={category.id}
                  id={optionId(i)}
                  role="option"
                  aria-selected={i === active}
                  onMouseDown={(e) => e.preventDefault()}
                  onClick={() => chooseResult(category)}
                  className={`flex cursor-pointer items-center justify-between gap-3 border-b border-line px-1 py-3 text-[14.5px] ${
                    i === active ? "rounded-[10px] px-2.5 outline-2 outline-mint" : ""
                  }`}
                >
                  <span className="min-w-0">
                    {path.length > 0 && (
                      <>
                        <span className="block text-[12px] text-ink-soft">
                          {path.join(CATEGORY_PATH_SEPARATOR)} {CHEVRON}
                        </span>{" "}
                      </>
                    )}
                    <span className="block font-bold text-ink">{highlight(category.name, needle)}</span>
                  </span>
                  {!isLeaf(index, category.id) && (
                    <span aria-hidden="true" className="text-base text-ink-soft">
                      {CHEVRON}
                    </span>
                  )}
                </li>
              ))}
            </ul>
          )}
        </>
      ) : (
        <>
          {current && (
            <button
              type="button"
              onClick={() => goTo(current.parent_id)}
              className={`${TEXT_BTN_CLASS} mb-1 mt-3 text-[13px] text-mint hover:text-mint`}
            >
              ‹ Wstecz
            </button>
          )}
          <nav aria-label="Ścieżka" className="mb-2 mt-3.5 flex flex-wrap items-center gap-1 text-[12.5px] text-ink-soft">
            {current ? (
              <button type="button" onClick={() => goTo(null)} className={TEXT_BTN_CLASS}>
                Wszystkie
              </button>
            ) : (
              <b className="text-ink">Wszystkie</b>
            )}
            {crumbs.map((name, depth) => (
              <span key={depth} className="flex items-center gap-1">
                <span aria-hidden="true">{CHEVRON}</span>
                {depth === crumbs.length - 1 ? (
                  <b className="text-ink">{name}</b>
                ) : (
                  <button type="button" onClick={() => goTo(ancestorAt(depth))} className={TEXT_BTN_CLASS}>
                    {name}
                  </button>
                )}
              </span>
            ))}
          </nav>

          {(allowRoot || (mode === "any" && current)) && (
            <div className="mb-2 flex flex-wrap gap-2">
              {mode === "any" && current && (
                <button
                  type="button"
                  onClick={() => onSelect(current.id)}
                  className="rounded-[10px] bg-mint px-3 py-2 text-[13px] font-extrabold text-white"
                >
                  Wybierz „{current.name}”
                </button>
              )}
              {allowRoot && (
                <button
                  type="button"
                  onClick={() => onSelect(null)}
                  className="rounded-[10px] border border-line px-3 py-2 text-[13px] font-extrabold text-ink-soft"
                >
                  {ROOT_LABEL}
                </button>
              )}
            </div>
          )}

          <ul ref={listRef} aria-label={current?.name ?? "Wszystkie"} className="flex flex-col">
            {rows.map((category) => {
              const leaf = isLeaf(index, category.id);
              return (
                <li key={category.id}>
                  <button
                    type="button"
                    aria-current={category.id === value || undefined}
                    onClick={() => (leaf ? onSelect(category.id) : goTo(category.id))}
                    className={`${ROW_CLASS} ${category.id === value ? "rounded-[10px] bg-primary-soft px-2.5 font-bold" : ""}`}
                  >
                    <span>{category.name}</span>
                    {leaf ? (
                      <span aria-hidden="true" className="text-[12px] text-ink-soft">
                        wybierz
                      </span>
                    ) : (
                      <span aria-hidden="true" className="text-base text-ink-soft">
                        {CHEVRON}
                      </span>
                    )}
                  </button>
                </li>
              );
            })}
          </ul>
        </>
      )}
    </ModalSheet>
  );
}

/** Wraps the first diacritic-insensitive match of `needle` in `<mark>`. */
function highlight(name: string, needle: string): ReactNode {
  if (!needle) return name;
  const chars = Array.from(name);
  const offsets: number[] = [];
  let folded = "";
  for (const char of chars) {
    offsets.push(folded.length);
    folded += foldCategoryText(char);
  }
  const at = folded.indexOf(needle);
  if (at < 0) return name;
  const startChar = offsets.findLastIndex((offset) => offset <= at);
  const endIndex = offsets.findIndex((offset) => offset >= at + needle.length);
  const endChar = endIndex < 0 ? chars.length : endIndex;
  return (
    <>
      {chars.slice(0, startChar).join("")}
      <mark className="rounded-sm bg-primary-soft text-ink">{chars.slice(startChar, endChar).join("")}</mark>
      {chars.slice(endChar).join("")}
    </>
  );
}

import {
  Package,
  LayoutList,
  Leaf,
  Plug,
  CalendarDays,
  UsersRound,
  Tag,
  Users,
  Warehouse,
  Image as ImageIcon,
  Images,
  ArrowLeftRight,
  Backpack,
  type LucideIcon,
} from "lucide-react";
import * as icons from "lucide-react";

export const ProductsIcon = Package;
export const PluginsIcon = Plug;
export const WarehouseIcon = Warehouse;
export const KragIcon = Users;
export const CategoriesIcon = Tag;
export const GroupsIcon = UsersRound;
export const TermsIcon = CalendarDays;
export const PhotosIcon = Images;
/** "Udostępnia" avatar-corner marker (Avatar's `showsSharesIcon`). */
export const SharesIcon = ArrowLeftRight;
/** "Przynosi" avatar-corner marker (Avatar's `showsBringsIcon`). */
export const BringsIcon = Backpack;

const ICON_MAP: Record<string, LucideIcon> = {
  package: Package,
  "layout-list": LayoutList,
  plug: Plug,
  warehouse: Warehouse,
  footprint: Leaf,
};

export function resolveIcon(name?: string): LucideIcon {
  if (!name) return Plug;

  if (ICON_MAP[name]) return ICON_MAP[name];

  // Convert kebab-case "arrow-right" to PascalCase "ArrowRight" for lucide lookup
  const pascalCase = name
    .split("-")
    .map((s) => s.charAt(0).toUpperCase() + s.slice(1))
    .join("");

  const icon = (icons as Record<string, unknown>)[pascalCase];
  if (typeof icon === "function") return icon as LucideIcon;

  return Plug;
}

export function PhotoPlaceholder({ size = 24 }: { size?: number }) {
  return <ImageIcon size={size} stroke="#94a3b8" strokeWidth={1.5} />;
}

import { ArrowLeft, ArrowRight, ChevronLeft, ChevronRight, Plus } from "lucide-react";
import { useEffect, useRef, useState, type RefObject } from "react";
import type { ModerationStatus } from "../../api/products";
import { ACCEPTED_PHOTO_TYPES } from "../../features/items/product/itemPageShared";
import { TrashIcon } from "./appIcons";
import { PhotoPlaceholder } from "./Icons";

export type ModerationLabels = Record<Exclude<ModerationStatus, "APPROVED">, string>;

const STATUS_LABELS: ModerationLabels = {
  PENDING: "W moderacji",
  NEEDS_REVIEW: "Do sprawdzenia",
  REJECTED: "Odrzucone",
};

/** Owner-only marker on a photo others can't see yet. */
export function ModerationBadge({
  status,
  labels = STATUS_LABELS,
}: {
  status: ModerationStatus;
  labels?: ModerationLabels;
}) {
  if (status === "APPROVED") return null;
  const tone = status === "REJECTED" ? "bg-danger-soft text-danger" : "bg-cream text-ink-soft";
  return <span className={`rounded-full px-2 py-0.5 text-[10.5px] font-extrabold ${tone}`}>{labels[status]}</span>;
}

interface PhotoFileFieldProps {
  disabled: boolean;
  label?: string;
  multiple?: boolean;
  /** Classes on the button-like label: spacing (default `mt-2`), a 44px touch height. */
  className?: string;
  onFiles: (files: File[]) => void;
  inputRef?: RefObject<HTMLInputElement | null>;
}

/** "+ Dodaj zdjęcia" by default — picks one or more image files (on phones
 * also the camera). Validation stays with the caller. */
export function PhotoFileField({
  disabled,
  label = "+ Dodaj zdjęcia",
  multiple = true,
  className = "mt-2",
  onFiles,
  inputRef,
}: PhotoFileFieldProps) {
  return (
    <label
      className={`inline-flex cursor-pointer items-center rounded-[9px] bg-primary px-3 py-1.5 text-[11.5px] font-extrabold text-on-primary focus-within:ring-2 focus-within:ring-focus-ring/40 ${
        disabled ? "pointer-events-none opacity-60" : ""
      } ${className}`}
    >
      {label}
      <FileInput
        label={label.replace(/^\+\s*/, "")}
        multiple={multiple}
        disabled={disabled}
        onFiles={onFiles}
        inputRef={inputRef}
      />
    </label>
  );
}

function FileInput({
  label,
  multiple,
  disabled,
  onFiles,
  inputRef,
}: {
  label: string;
  multiple: boolean;
  disabled: boolean;
  onFiles: (files: File[]) => void;
  inputRef?: RefObject<HTMLInputElement | null>;
}) {
  return (
    <input
      ref={inputRef}
      type="file"
      accept={ACCEPTED_PHOTO_TYPES}
      multiple={multiple}
      aria-label={label}
      disabled={disabled}
      onChange={(e) => {
        const files = Array.from(e.target.files ?? []);
        e.target.value = "";
        if (files.length > 0) onFiles(files);
      }}
      className="sr-only"
    />
  );
}

export interface GalleryPhoto {
  /** Stable key, also handed back to `onRemove`/`onMove`. */
  id: string;
  src: string;
  status?: ModerationStatus;
}

interface PhotoGalleryFieldProps {
  photos: GalleryPhoto[];
  /** With 1 the slider is a single wide banner. */
  max: number;
  disabled: boolean;
  /** Picked files; validation stays with the caller. */
  onFiles: (files: File[]) => void;
  onRemove: (id: string) => void;
  /** Adds "earlier/later" buttons to every photo. */
  onMove?: (id: string, direction: "up" | "down") => void;
  /** Accessible noun of one photo: "Usuń zdjęcie 2", or "Usuń baner" when `max` is 1. */
  noun?: string;
  addLabel?: string;
  /** "create": while empty, one large "+" tile; "edit": an empty slider with the corner button. */
  variant?: "create" | "edit";
  /** Edge to edge at the top of a page whose content sheet overlaps the bottom 24px. */
  fullBleed?: boolean;
}

/** The shared photo editor: a slider with "Usuń" on every photo and the
 * main "Dodaj" button in its top corner; the "create" variant shows a large
 * "+" tile instead while empty. */
export function PhotoGalleryField({
  photos,
  max,
  disabled,
  onFiles,
  onRemove,
  onMove,
  noun = "zdjęcie",
  addLabel = "Dodaj zdjęcia",
  variant = "edit",
  fullBleed = false,
}: PhotoGalleryFieldProps) {
  const single = max === 1;
  const multiple = !single;
  // A rejected photo stays visible to its owner but doesn't use up the limit.
  const atLimit = photos.filter((p) => p.status !== "REJECTED").length >= max;
  // Follows the shown photo by id across reorders; after a removal the slider
  // stays at the same position.
  const [active, setActive] = useState<{ id: string | null; index: number }>({ id: null, index: 0 });
  const found = photos.findIndex((p) => p.id === active.id);
  const current = found !== -1 ? found : Math.min(active.index, Math.max(photos.length - 1, 0));
  const photo = photos[current];
  const focusAfterMove = useRef<"up" | "down" | null>(null);
  const moveUpRef = useRef<HTMLButtonElement>(null);
  const moveDownRef = useRef<HTMLButtonElement>(null);
  const shape = single ? "aspect-video" : "aspect-4/3";

  useEffect(() => {
    if (disabled || !focusAfterMove.current) return;
    const [target, fallback] =
      focusAfterMove.current === "up" ? [moveUpRef, moveDownRef] : [moveDownRef, moveUpRef];
    (target.current && !target.current.disabled ? target.current : fallback.current)?.focus();
    focusAfterMove.current = null;
  }, [disabled, photos]);

  if (photos.length === 0 && variant === "create") {
    return (
      <label
        className={`mt-2 flex w-full cursor-pointer flex-col items-center justify-center gap-1 rounded-2xl border-2 border-dashed border-line-strong bg-cream text-ink-soft hover:border-primary hover:text-ink focus-within:ring-2 focus-within:ring-focus-ring/40 ${shape} ${
          disabled ? "pointer-events-none opacity-60" : ""
        }`}
      >
        <Plus size={48} strokeWidth={1.75} aria-hidden="true" />
        <span className="text-[13px] font-extrabold">{addLabel}</span>
        <FileInput label={addLabel} multiple={multiple} disabled={disabled} onFiles={onFiles} />
      </label>
    );
  }

  function show(index: number) {
    setActive({ id: photos[index].id, index });
  }

  function move(direction: "up" | "down") {
    if (!onMove || !photo) return;
    focusAfterMove.current = direction;
    onMove(photo.id, direction);
  }

  const name = single ? noun : `${noun} ${current + 1}`;
  const overlayButton =
    "flex h-10 items-center justify-center gap-1.5 rounded-full bg-paper/90 text-[13px] font-extrabold text-ink shadow-md hover:bg-paper focus-visible:outline-2 focus-visible:outline-focus-ring disabled:opacity-40";

  return (
    <div
      className={`relative overflow-hidden bg-primary-soft ${shape} ${fullBleed ? "" : "mt-2 rounded-2xl border border-line"}`}
    >
      {photo ? (
        <TileImage key={photo.src} src={photo.src} />
      ) : (
        <span className="flex h-full w-full flex-col items-center justify-center gap-2 pb-6 text-sm font-bold text-primary-fg">
          <PhotoPlaceholder size={48} />
          Brak zdjęć
        </span>
      )}

      {!atLimit ? (
        <PhotoFileField
          disabled={disabled}
          label={`+ ${addLabel}`}
          multiple={multiple}
          className={`absolute right-3 min-h-10 rounded-full px-4 text-[13px] shadow-md ${fullBleed ? "top-3.5" : "top-3"}`}
          onFiles={onFiles}
        />
      ) : (
        multiple && (
          <span
            className={`absolute right-3 rounded-full bg-paper/90 px-3 py-1.5 text-[11.5px] font-extrabold text-ink-soft shadow-md ${fullBleed ? "top-3.5" : "top-3"}`}
          >
            Osiągnięto limit {max} zdjęć
          </span>
        )
      )}

      {photos.length > 1 && (
        <>
          <button
            type="button"
            aria-label="Poprzednie zdjęcie"
            disabled={current === 0}
            onClick={() => show(current - 1)}
            className={`absolute top-1/2 left-3 w-10 -translate-y-1/2 ${overlayButton}`}
          >
            <ChevronLeft size={20} aria-hidden="true" />
          </button>
          <button
            type="button"
            aria-label="Następne zdjęcie"
            disabled={current === photos.length - 1}
            onClick={() => show(current + 1)}
            className={`absolute top-1/2 right-3 w-10 -translate-y-1/2 ${overlayButton}`}
          >
            <ChevronRight size={20} aria-hidden="true" />
          </button>
        </>
      )}

      {photo && (
        <div className={`absolute inset-x-3 flex items-end justify-between gap-2 ${fullBleed ? "bottom-9" : "bottom-3"}`}>
          <span className="flex min-w-0 flex-wrap items-center gap-1.5">
            {multiple && (
              <span className="rounded-full bg-paper/90 px-2.5 py-0.5 text-[11.5px] font-extrabold text-ink">
                {current + 1} / {photos.length}
              </span>
            )}
            {photo.status && <ModerationBadge status={photo.status} />}
          </span>
          <span className="flex flex-none gap-1.5">
            {onMove && (
              <>
                <button
                  ref={moveUpRef}
                  type="button"
                  aria-label={`Przesuń ${name} wcześniej`}
                  disabled={disabled || current === 0}
                  onClick={() => move("up")}
                  className={`w-10 ${overlayButton}`}
                >
                  <ArrowLeft size={16} aria-hidden="true" />
                </button>
                <button
                  ref={moveDownRef}
                  type="button"
                  aria-label={`Przesuń ${name} dalej`}
                  disabled={disabled || current === photos.length - 1}
                  onClick={() => move("down")}
                  className={`w-10 ${overlayButton}`}
                >
                  <ArrowRight size={16} aria-hidden="true" />
                </button>
              </>
            )}
            <button
              type="button"
              disabled={disabled}
              onClick={() => onRemove(photo.id)}
              className={`px-3.5 hover:text-danger ${overlayButton}`}
            >
              <TrashIcon /> Usuń{" "}
              <span className="sr-only">{name}</span>
            </button>
          </span>
        </div>
      )}
    </div>
  );
}

/** Thumbnail filling its tile; a failed load shows the placeholder instead. */
function TileImage({ src }: { src: string }) {
  const [failedSrc, setFailedSrc] = useState<string | null>(null);
  if (failedSrc === src) {
    return (
      <span className="flex h-full w-full items-center justify-center">
        <PhotoPlaceholder size={24} />
      </span>
    );
  }
  return (
    <img
      src={src}
      alt=""
      loading="lazy"
      referrerPolicy="no-referrer"
      onError={() => setFailedSrc(src)}
      className="h-full w-full object-cover"
    />
  );
}

import { useRef } from "react";
import { initials } from "../../utils/appHelpers";
import { useAppData } from "../panel/appDataStore";
import { useProfileForm } from "./useProfileForm";

const AVATAR_STATUS_NOTE: Record<string, string> = {
  PENDING: "Zdjęcie czeka na moderację — do tego czasu widzisz je tylko Ty.",
  NEEDS_REVIEW: "Zdjęcie czeka na sprawdzenie przez moderatora.",
  REJECTED: "Zdjęcie zostało odrzucone przez moderację. Wgraj inne.",
};

const INPUT_CLASS =
  "rounded-xl border-[1.5px] border-line bg-cream px-3.5 py-2.5 text-ink focus:border-mint focus:outline-none focus:ring-[3px] focus:ring-mint-soft";

export function ProfileView() {
  const { profile } = useAppData();
  const {
    name: profileName,
    setName: setProfileName,
    bio: profileBio,
    setBio: setProfileBio,
    saved: profileSaved,
    error: profileError,
    avatarBusy,
    avatarError,
    save: saveProfile,
    changeAvatar,
    removeAvatar,
  } = useProfileForm();
  const fileInput = useRef<HTMLInputElement>(null);

  if (!profile) return null;

  const avatar = profile.avatar;
  const statusNote = avatar ? AVATAR_STATUS_NOTE[avatar.status] : undefined;

  return (
    <div className="rounded-[22px] border border-line bg-paper p-5">
      <h3 className="mb-3.5 text-base font-semibold text-ink">Dane profilowe</h3>
