            id="panel-name"
            value={profileName}
            onChange={(e) => setProfileName(e.target.value)}
            maxLength={255}
            className={INPUT_CLASS}
          />
        </div>
        <div className="flex flex-col gap-1.5">
          <label htmlFor="panel-bio" className="text-xs font-extrabold tracking-wide text-ink-soft">
            O mnie
          </label>
          <textarea
            id="panel-bio"
            value={profileBio}
            onChange={(e) => setProfileBio(e.target.value)}
            maxLength={1000}
            placeholder="Kilka zdań o Tobie"
            className={`min-h-[76px] resize-y ${INPUT_CLASS}`}
          />
        </div>
      </div>
      <div className="mt-4 flex flex-col gap-2.5">
        {profileError && (
          <p role="alert" className="text-center text-[13px] font-bold text-red-600">
            {profileError}
          </p>
        )}
        {profileSaved && <span className="text-center text-[13px] font-bold text-mint">✓ Zapisano</span>}
        <button
          onClick={() => void saveProfile()}
          disabled={!profileName.trim()}
          className="w-full rounded-[13px] bg-mint px-5 py-3 text-[13.5px] font-extrabold text-white shadow-[0_8px_18px_-10px_rgba(27,129,104,0.85)] transition-transform hover:-translate-y-0.5 disabled:opacity-60"
        >
          Zapisz zmiany
        </button>
      </div>
    </div>
  );
}

import {
  Box,
  Button,
  Flex,
  Grid,
  Heading,
  Input,
  Text,
  Textarea,
} from "@chakra-ui/react";
import { useQueryClient } from "@tanstack/react-query";
import { useCallback, useEffect, useState } from "react";
import { Link, useAppNavigate, useAppParams } from "../../routing/navigation";
import { getProduct, createProduct, updateProduct } from "../../api/products";
import { serverMessageOr } from "../../api/problem";
import { CategoryTreePicker } from "../../components/shared/CategoryTreePicker";
import { CATEGORIES_KEY } from "../../hooks/useCategories";
import { PhotoPlaceholder } from "../../components/shared/Icons";
import { isValidImageUrl } from "../../utils/url";
import { PrimaryButton } from "../../components/shared/PrimaryButton";

const labelStyle: React.CSSProperties = {
  fontSize: "14px",
  fontWeight: 600,
  color: "#334155",
  display: "block",
  marginBottom: "6px",
};

const CATEGORY_LABEL_ID = "product-category-label";
const CATEGORY_ERROR_ID = "product-category-error";

export function ProductFormPage() {
  const { id } = useAppParams<{ id: string }>();
  const navigate = useAppNavigate();
  const queryClient = useQueryClient();
  const isEdit = Boolean(id);

  const [name, setName] = useState("");
  const [sku, setSku] = useState("");
  const [categoryId, setCategoryId] = useState<string>("");
  const [description, setDescription] = useState("");
  const [photoUrl, setPhotoUrl] = useState("");
  const [loading, setLoading] = useState(false);
  const [loadingData, setLoadingData] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [categoryMissing, setCategoryMissing] = useState(false);

  const loadData = useCallback(async () => {
    setLoadingData(true);
    try {
      if (id) {
        const product = await getProduct(id);
        setName(product.name);
        setSku(product.sku);
        setCategoryId(product.category_id);
        setDescription(product.description ?? "");
        setPhotoUrl(product.photo_url ?? "");
      }
    } catch {
      setError("Failed to load data.");
    } finally {
      setLoadingData(false);
    }
  }, [id]);

  useEffect(() => {
    void loadData();
  }, [loadData]);

  async function handleSubmit(e: React.FormEvent) {
    e.preventDefault();
    if (!categoryId) {
      setCategoryMissing(true);
      return;
    }
    setLoading(true);
    setError(null);
    const payload = {
      name,
      sku,
      category_id: categoryId,
      description: description || undefined,
      photo_url: photoUrl || undefined,
    };
    try {
      if (isEdit && id) {
        await updateProduct(id, payload);
      } else {
        await createProduct(payload);
      }
      // A product write changes `product_count`, which the cached category tree shows.
      await queryClient.invalidateQueries({ queryKey: CATEGORIES_KEY });
      navigate("/admin/products");
    } catch (err) {
      setError(serverMessageOr(err, "Failed to save product."));
    } finally {
      setLoading(false);
    }
  }

  if (loadingData) {
    return <Text>Loading...</Text>;
  }

  return (
    <Box maxW="800px">
      <Box mb="24px">
        <Flex as="nav" fontSize="13px" color="#64748B" gap="4px" aria-label="Breadcrumb">
          <Link to="/admin/products" style={{ color: "var(--chakra-colors-brand-600)", textDecoration: "none" }}>
            Products
          </Link>
          <Text as="span">/</Text>
          <Text as="span">{isEdit ? "Edit Product" : "Add New Product"}</Text>
        </Flex>
        <Heading as="h1" fontSize="24px" fontWeight="700" color="#0F172A" mt="4px">
          {isEdit ? "Edit Product" : "Add New Product"}
        </Heading>
      </Box>

      <Box as="form" onSubmit={handleSubmit} bg="white" border="1px solid" borderColor="#E2E8F0" borderRadius="12px" p="32px">
        <Grid templateColumns={{ base: "1fr", md: "1fr 1fr" }} gap="20px">
          <Box>
            <label htmlFor="product-name" style={labelStyle}>
              Product Name <Text as="span" color="#EF4444">*</Text>
            </label>
            <Input
              id="product-name"
              value={name}
              onChange={(e) => setName(e.target.value)}
              placeholder="e.g. Wireless Headphones Pro"
              required
            />
          </Box>

          <Box>
            <label htmlFor="product-sku" style={labelStyle}>
              SKU <Text as="span" color="#EF4444">*</Text>
            </label>
            <Input
              id="product-sku"
              value={sku}
              onChange={(e) => setSku(e.target.value)}
              placeholder="e.g. WHP-001"
              required
            />
            <Text fontSize="12px" color="#94A3B8" mt="6px">
              Unique stock keeping unit identifier
            </Text>
          </Box>

          <Box>
            <span id={CATEGORY_LABEL_ID} style={labelStyle}>
              Category <Text as="span" color="#EF4444">*</Text>
            </span>
            <CategoryTreePicker
              labelledBy={CATEGORY_LABEL_ID}
              value={categoryId}
              onChange={(next) => {
                setCategoryId(next ?? "");
                setCategoryMissing(false);
              }}
              placeholder="Select a category..."
              aria-invalid={categoryMissing}
              aria-describedby={categoryMissing ? CATEGORY_ERROR_ID : undefined}
            />
            {categoryMissing && (
              <Text id={CATEGORY_ERROR_ID} role="alert" fontSize="12px" color="#DC2626" mt="6px">
                Select a category.
              </Text>
            )}
          </Box>

          <Box gridColumn={{ base: "1", md: "1 / -1" }}>
            <label htmlFor="product-description" style={labelStyle}>
              Description
            </label>
            <Textarea
              id="product-description"
              value={description}
              onChange={(e) => setDescription(e.target.value)}
              placeholder="Describe your product..."
              rows={4}
            />
          </Box>

          <Box gridColumn={{ base: "1", md: "1 / -1" }}>
            <label htmlFor="product-photo-url" style={labelStyle}>
              Photo URL
            </label>
            <Input
              id="product-photo-url"
              type="url"
              value={photoUrl}
              onChange={(e) => setPhotoUrl(e.target.value)}
              placeholder="https://example.com/image.jpg"
            />
            <Text fontSize="12px" color="#94A3B8" mt="6px">
              External URL to product image
            </Text>
            <Box mt="8px">
              {isValidImageUrl(photoUrl) ? (
                <Box
                  w="120px"
                  h="120px"
                  borderRadius="12px"
                  overflow="hidden"
                  border="1px solid"
                  borderColor="#E2E8F0"
                >
                  <img src={photoUrl} alt="Preview" style={{ width: "100%", height: "100%", objectFit: "cover" }} />
                </Box>
              ) : (
                <Flex
                  w="120px"
                  h="120px"
                  border="2px dashed"
                  borderColor="#E2E8F0"
                  borderRadius="12px"
                  align="center"
                  justify="center"
                  direction="column"
                  gap="8px"
                  color="#94A3B8"
                  fontSize="11px"
                  textAlign="center"
                  p="8px"
                >
                  <PhotoPlaceholder size={32} />
                  <span>Image preview</span>
                </Flex>
              )}
            </Box>
          </Box>
        </Grid>

        {error && (
          <Box role="alert" mt="16px" p="12px" bg="#FEE2E2" borderRadius="8px" fontSize="13px" color="#991B1B">
            {error}
          </Box>
        )}

        <Flex justify="flex-end" gap="12px" mt="28px" pt="20px" borderTop="1px solid" borderColor="#F1F5F9">
          <Button asChild variant="outline">
            <Link to="/admin/products">Cancel</Link>
          </Button>
          <PrimaryButton type="submit" loading={loading}>
            Save Product
          </PrimaryButton>
        </Flex>
      </Box>
    </Box>
  );
}

import { useEffect, useState } from "react";
import type { Step, StepContext } from "../OnboardingWizard";
import { createMyCircle, type GroupResponse } from "../../../../api/groups";
import { createTerm } from "../../../../api/terms";
import { createMyOrganization } from "../../../../api/organizations";

const inputClass =
  "w-full rounded-xl border-[1.5px] border-line bg-cream px-3.5 py-2.5 text-sm text-ink outline-none focus:border-mint focus:ring-[3px] focus:ring-mint-soft";
const labelClass = "mb-1.5 block text-xs font-extrabold tracking-wide text-ink-soft";

/**
 * Holds the circle created by step 1 for step 2 to reference (`Grupa:
 * {step1 value}` in the mockup, and `circle_group_id` for `createTerm`).
 * Module-scoped rather than lifted into `OnboardingWizard`'s generic
 * `Step` contract — the wizard shell has no notion of cross-step state,
 * and only one onboarding flow is ever in progress per browser session.
 */
let createdCircle: GroupResponse | null = null;

/* ------------------------------------------------------------------ */
/*  Step 1/3 — Nazwa organizacji: mandatory (isSkippable: false, see     */
/*  export below) — every ORGANIZER account gets an Organization brand   */
/*  identity, per the "full pakiet" requirement. Throws (rather than      */
/*  silently no-op'ing like the skippable steps below) on an empty name  */
/*  so `OnboardingWizard.handleAdvance` blocks advancing instead of       */
/*  quietly skipping creation.                                           */
/* ------------------------------------------------------------------ */

function OrganizationNameStepBody({ ctx }: { ctx: StepContext }) {
  const [name, setName] = useState("");

  useEffect(() => {
    ctx.setSubmit(async () => {
      if (!name.trim()) throw new Error("Nazwa organizacji jest wymagana");
      await createMyOrganization({ name: name.trim() });
    });
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [name]);

  return (
    <div>
      <label htmlFor="onboarding-organization-name" className={labelClass}>
        Nazwa organizacji
      </label>
      <input
        id="onboarding-organization-name"
        className={inputClass}
        placeholder="np. Muzyczne Skrzaty"
        value={name}
        onChange={(e) => setName(e.target.value)}
      />
      <p className="mt-1.5 text-xs text-ink-soft">
        Własną stronę organizacji (z kolorami) skonfigurujesz później w menu.
      </p>
    </div>
  );
}

/* ------------------------------------------------------------------ */
/*  Step 2/3 — Nazwa grupy: reuses createMyCircle()/handleAddGroup()'s   */
/*  logic (single text input + submit).                                 */
/* ------------------------------------------------------------------ */

function CircleNameStepBody({ ctx }: { ctx: StepContext }) {
  const [name, setName] = useState("");

  useEffect(() => {
    ctx.setSubmit(async () => {
      if (!name.trim()) return;
      createdCircle = await createMyCircle({ name: name.trim() });
    });
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [name]);

  return (
    <div>
      <label htmlFor="onboarding-circle-name" className={labelClass}>
        Nazwa grupy
      </label>
      <input
        id="onboarding-circle-name"
        className={inputClass}
        placeholder="np. Muzyczne Maluchy"
        value={name}
        onChange={(e) => setName(e.target.value)}
      />
    </div>
  );
}

/* ------------------------------------------------------------------ */
/*  Step 3/3 — Termin zajęć: Grupa/Data/Opis only; needed items are    */
/*  added later from the panel's term modal.                            */
/* ------------------------------------------------------------------ */

function TermStepBody({ ctx }: { ctx: StepContext }) {
  const [occursOn, setOccursOn] = useState("");
  const [description, setDescription] = useState("");

  useEffect(() => {
    ctx.setSubmit(async () => {
      if (!occursOn || !createdCircle) return;
      await createTerm({
        circle_group_id: createdCircle.id,
        occurs_on: occursOn,
        description: description || undefined,
      });
    });
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [occursOn, description]);

  return (
    <div className="flex flex-col gap-3">
      <div>
        <span className={labelClass}>Grupa</span>
        <p className="rounded-xl border-[1.5px] border-line bg-cream px-3.5 py-2.5 text-sm text-ink-soft">
          {createdCircle?.name ?? "—"}
        </p>
      </div>

      <div>
        <label htmlFor="onboarding-term-date" className={labelClass}>
          Data i godzina
        </label>
        <input
          id="onboarding-term-date"
          type="datetime-local"
          className={inputClass}
          value={occursOn}
          onChange={(e) => setOccursOn(e.target.value)}
        />
      </div>

      <div>
        <label htmlFor="onboarding-term-description" className={labelClass}>
          Opis (opcjonalnie)
        </label>
        <input
          id="onboarding-term-description"
          className={inputClass}
          placeholder="17:00 · Park Sołacki · wstęp wolny"
          value={description}
          onChange={(e) => setDescription(e.target.value)}
        />
      </div>
    </div>
  );
}

export const organizerSteps: Step[] = [
  {
    id: "organization-name",
    title: "Nazwa organizacji",
    isSkippable: false,
    render: (ctx) => <OrganizationNameStepBody ctx={ctx} />,
  },
  {
    id: "circle-name",
    title: "Nazwa grupy",
    isSkippable: true,
    render: (ctx) => <CircleNameStepBody ctx={ctx} />,
  },
  {
    id: "term",
    title: "Termin zajęć",
    isSkippable: true,
    render: (ctx) => <TermStepBody ctx={ctx} />,
  },
];

import { useEffect, type ReactNode } from "react";
import { useAppNavigate, useAppParams, useNavigationState } from "../../routing/navigation";
import type { EventDetailResponse } from "../../api/events";
import { useAuth } from "../../auth/AuthContext";
import { ConfirmDeleteDialog } from "../../components/shared/ConfirmDeleteDialog";
import { ToastPill } from "../../components/shared/ToastPill";
import { useToast } from "../../components/shared/useToast";
import { PAGE_SHELL } from "../../components/shared/uiStyles";
import { useEvent } from "../../hooks/useEvent";
import { useOpenAndNavigate } from "../../hooks/useOpenAndNavigate";
import { useOrigin } from "../../lib/useClientValue";
import { OrganizerThemeScope } from "../../theme/OrganizerThemeScope";
import { eventPath, viewPath } from "../../routing/paths";
import { GroupHeader } from "../terms/components/GroupHeader";
import { TermPageSkeleton } from "../terms/components/TermPageSkeleton";
import { EventAttendeeList } from "./components/EventAttendeeList";
import { EventAuthorCard } from "./components/EventAuthorCard";
import { EventChatRow } from "./components/EventChatRow";
import { EventFooter } from "./components/EventFooter";
import { EventGuestMergeCard } from "./components/EventGuestMergeCard";
import { EventGuestSignUpSheet } from "./components/EventGuestSignUpSheet";
import { EventWhenCard } from "./components/EventWhenCard";
import { resolveEventView } from "./eventViewState";
import { useEventSignUp } from "./hooks/useEventSignUp";

const RETRY_BUTTON =
  "mt-3 rounded-xl border border-line bg-paper px-4 py-2 text-[13px] font-semibold text-ink hover:bg-cream";

/** A toast handed over in router state, e.g. by the create flow. */
function routerToast(state: unknown): string | null {
  return typeof state === "object" && state !== null && "toast" in state && typeof state.toast === "string"
    ? state.toast
    : null;
}

/** Route element for `/:organizationSlug/event/:eventId`: the public page of
 * a one-off event. Keyed on the id, since React Router reuses the element
 * when only `:eventId` changes and the page state belongs to one event. */
export function EventPage() {
  const { eventId = "" } = useAppParams();
  return <EventPageContent key={eventId} eventId={eventId} />;
}

/** Shows exactly one view per `resolveEventView` state; sign-up and withdraw
 * live in `useEventSignUp`. */
function EventPageContent({ eventId }: { eventId: string }) {
  const { token } = useAuth();
  const isLoggedIn = Boolean(token);
  const navigate = useAppNavigate();
  const state = useNavigationState<unknown>();
  const event = useEvent(eventId);
  const { toast, showToast } = useToast();
  const chat = useOpenAndNavigate();
  const signUp = useEventSignUp({
    eventId,
    isLoggedIn,
    signUp: event.signUp,
    withdraw: event.withdraw,
    showToast,
  });
  const view = resolveEventView({
    data: event.data,
    loading: event.loading,
    notFound: event.notFound,
    error: event.error,
    isStale: event.isStale,
    isLoggedIn,
    guestProfileId: signUp.guestProfileId,
  });

  // Shown once: the handed-over state is read once, so a refresh or a back
  // navigation doesn’t repeat it.
  const handedOverToast = routerToast(state);
  useEffect(() => {
    if (handedOverToast === null) return;
    showToast(handedOverToast);
  }, [handedOverToast, showToast]);

  const page = (content: EventDetailResponse, sections: Omit<EventShellProps, "event" | "onCopyLink">) => (
    <EventShell event={content} onCopyLink={() => showToast("Skopiowano link")} {...sections} />
  );
  const chatRow = (id: string) => (
    <EventChatRow onOpen={() => void chat.open({ kind: "EVENT", id })} busy={chat.busy} error={chat.error} />
  );

  const body = (() => {
    switch (view.kind) {
      case "loading":
        return <TermPageSkeleton />;
      case "notFound":
        return <p className="px-5 pt-6 text-[12.5px] text-ink-soft">Nie znaleziono wydarzenia.</p>;
      case "error":
        return (
          <div className="px-5 pt-6">
            <p role="alert" className="text-[12.5px] font-semibold text-danger">
              Nie udało się wczytać wydarzenia — {view.message}
            </p>
            <button type="button" onClick={() => void event.refetch()} className={RETRY_BUTTON}>
              Spróbuj ponownie
            </button>
          </div>
        );
      case "refreshing":
        return page(view.event, {
          card: view.error && (
            <div className="mx-5 mt-6">
              <p role="alert" className="text-[12.5px] font-semibold text-danger">
                Nie udało się odświeżyć wydarzenia — {view.error}
              </p>
              <button type="button" onClick={() => void event.refetch()} className={RETRY_BUTTON}>
                Spróbuj ponownie
              </button>
            </div>
          ),
        });
      case "author":
        return page(view.event, {
          chat: chatRow(view.event.id),
          card: (
            <EventAuthorCard
              event={view.event}
              onDelete={async () => {
                await event.remove();
                navigate(viewPath("meetings"));
              }}
            />
          ),
        });
      case "attendee":
        return page(view.event, {
          chat: chatRow(view.event.id),
          footer: view.ended ? (
            <EventFooter variant="ended" />
          ) : (
            <EventFooter variant="withdraw" busy={false} onWithdraw={signUp.openWithdraw} />
          ),
          overlay: signUp.confirmingWithdraw && (
            <ConfirmDeleteDialog
              title="Wypisać się z wydarzenia?"
              body="Znikniesz z listy zapisanych i stracisz dostęp do czatu wydarzenia."
              confirmLabel="Wypisz się"
              tone="primary"
              busyLabel="Wypisywanie…"
              fallbackError="Nie udało się wypisać. Spróbuj ponownie."
              onConfirm={signUp.confirmWithdraw}
              onClose={signUp.closeWithdraw}
            />
          ),
        });
      case "guestAttendee":
        return page(view.event, { card: <EventGuestMergeCard guestProfileId={view.guestProfileId} /> });
      case "visitor":
        return page(view.event, {
          canSignUp: !view.ended,
          footer: view.ended ? (
            <EventFooter variant="ended" />
          ) : (
            <EventFooter variant="signUp" busy={signUp.signingUp} onSignUp={signUp.openSignUp} />
          ),
          overlay: signUp.sheetOpen && (
            <EventGuestSignUpSheet event={view.event} onSubmit={signUp.submitGuest} onClose={signUp.closeSheet} />
          ),
        });
    }
  })();

  return (
    <>
      {body}
      <ToastPill message={toast} />
    </>
  );
}

interface EventShellProps {
  event: EventDetailResponse;
  onCopyLink: () => void;
  /** The viewer may sign up, so the empty attendee list invites them to. */
  canSignUp?: boolean;
  /** The per-view parts, in page order; omitted ones render nothing. */
  chat?: ReactNode;
  card?: ReactNode;
  footer?: ReactNode;
  /** A sheet or dialog over the page. */
  overlay?: ReactNode;
}

/** The event page in the author's theme: header, banner, date and place,
 * description, chat, the attendee list, the view's card and footer. */
function EventShell({ event, onCopyLink, canSignUp = false, chat, card, footer, overlay }: EventShellProps) {
  const navigate = useAppNavigate();
  const origin = useOrigin();

  return (
    <OrganizerThemeScope theme={event.organization}>
      <div className={PAGE_SHELL}>
        <GroupHeader
          title={event.name}
          eyebrow="Wydarzenie"
          onBack={() => navigate(-1)}
          organizerName={event.author_display_name}
          // A `k-…` fallback slug has no organizer page: an author without an
          // Organization links to their person profile instead.
          organizerSlug={
            event.organization !== null
              ? event.author_slug
              : (event.participants.find((p) => p.is_author)?.party_id ?? null)
          }
        />
        <main tabIndex={-1} className="flex-1 pb-6 outline-none">
          {event.banner_url && (
            <img
              src={event.banner_url}
              alt={`Baner wydarzenia ${event.name}`}
              className="mx-5 block aspect-16/7 w-[calc(100%-2.5rem)] rounded-[22px] object-cover"
            />
          )}
          <EventWhenCard
            event={event}
            url={`${origin}${eventPath(event.author_slug, event.id)}`}
            onCopyLink={onCopyLink}
          />
          {event.description && (
            <p className="mx-5 mt-5 text-[15px] leading-relaxed whitespace-pre-line wrap-break-word text-ink">
              {event.description}
            </p>
          )}
          {chat}
          <EventAttendeeList
            participants={event.participants}
            authorSlug={event.author_slug}
            canSignUp={canSignUp}
          />
          {card}
        </main>
        {footer}
        {overlay}
      </div>
    </OrganizerThemeScope>
  );
}

import { useEffect, useRef, type RefObject } from "react";
import {
  Link,
  Navigate,
  useAppParams,
  useAppPathname,
  useAppSearch,
  useAppSearchParams,
  useNavigationState,
} from "../../../routing/navigation";
import type { ItemDetailsResponse } from "../../../api/items";
import { useAuth } from "../../../auth/AuthContext";
import { authPath } from "../../../auth/authPaths";
import { PhoneFrame } from "../../../components/shared/PhoneFrame";
import { useItemActions, type UseItemActionsResult } from "../../../hooks/useItemActions";
import { useItemDetail, useItemEditing, type ProductDetailsState } from "../../../hooks/useItemDetail";
import dayjs from "../../../utils/dayjs";
import { CONDITION_LABELS } from "../../../utils/productCategory";
import { PencilIcon, TrashIcon } from "../../../components/shared/appIcons";
import { ItemBackButton } from "./ItemBackButton";
import { ItemContextActions } from "./ItemContextActions";
import { resolveItemActionsView, type ItemActionsView } from "./itemActionsViewState";
import { ItemEditForm } from "./ItemEditForm";
import { ItemGallery } from "./ItemGallery";
import { ItemGalleryEditor } from "./ItemGalleryEditor";
