/** `/:partyId`: a person's public profile with a fixed layout — avatar,
 * name and bio, their nearest public date, their newest listed items, and
 * for the person themself an invite to set up an organizer page. A person
 * who owns an Organization is redirected to its page. */
export function PartyProfilePage() {
  const { organizationSlug: partyId = "" } = useAppParams<{ organizationSlug: string }>();
  const profile = usePartyProfile(partyId);

  if (profile.notFound) return <NotFoundFrame message="Ten profil nie istnieje albo nie jest publiczny." />;
  const slug = profile.data?.owner.slug;
  if (slug) return <Navigate to={`/${slug}`} replace />;

  const body = (() => {
    if (profile.loading) return <BlockSkeleton shape="grid" />;
    if (!profile.data) {
      return (
        <p className="text-[13px] text-ink-soft">
          Nie udało się wczytać profilu.{" "}
          <button type="button" onClick={() => void profile.refetch()} className={RETRY_BUTTON}>
            Spróbuj ponownie
          </button>
        </p>
      );
    }
    return <ProfileContent profile={profile.data} />;
  })();

  return (
    <PageFrame>
      <div className="mx-auto flex w-full max-w-[430px] flex-1 flex-col">
        <div className="flex flex-col gap-5 px-6 pt-4">
          <BackButton />
          {body}
        </div>
        <div className="flex-1" />
        <FooterBlock />
      </div>
    </PageFrame>
  );
}

import { useState } from "react";
import type { PublicMedia } from "../../../api/organizations";
import { familyInitials } from "../../../components/shared/Avatar";
import { isValidImageUrl } from "../../../utils/url";
import type { BlockProps } from "../layouts/types";
import { ShareButton } from "./ShareButton";

// Over a photo the name sits in the bottom third, which this fade keeps at the
// strong scrim (4.5:1 for on-ink text on any image); the top stays clear.
const COVER_SCRIM =
  "absolute inset-0 bg-gradient-to-b from-transparent from-10% via-scrim via-40% to-scrim-strong to-70%";
// LINKS: the same strong scrim under the name, then a fade into the page color.
const CENTERED_SCRIM =
  "absolute inset-0 bg-gradient-to-b from-scrim from-0% via-scrim-strong via-75% to-primary to-100%";

/** Whether an image URL can be shown: valid and not failed to load. */
function useImage(src: string | undefined) {
  const [failedSrc, setFailedSrc] = useState<string | null>(null);
  const shown = src !== undefined && src !== failedSrc && isValidImageUrl(src);
  return { shown, onError: () => setFailedSrc(src ?? null) };
}

/** The logo thumbnail, or the initials when there is none or it fails.
 * `className` carries the size and placement shared by both. */
function HeroLogo({
  logo,
  initials,
  className,
  initialsClassName,
}: {
  logo: PublicMedia | null;
  initials: string;
  className: string;
  initialsClassName: string;
}) {
  const image = useImage(logo?.thumb_url);
  if (logo && image.shown) {
    return (
      <img
        src={logo.thumb_url}
        alt=""
        referrerPolicy="no-referrer"
        onError={image.onError}
        className={`${className} rounded-full bg-paper object-cover`}
      />
    );
  }
  return (
    <span
      aria-hidden="true"
      className={`${className} flex items-center justify-center rounded-full ${initialsClassName}`}
    >
      {initials}
    </span>
  );
}

/** Organization name, logo (or initials) and public address. `cover` is a
 * primary color band, or the cover photo fading into a strong scrim when there
 * is one; `centered` is the LINKS hero on the primary page, its cover photo
 * fading into that color; `compact` is a top bar that carries the share action itself, under a
 * strip of the cover photo that the logo overlaps when there is one. */
export function HeroBlock({ data, variant, heroAction }: BlockProps) {
  const { name, slug, logo, cover } = data.organization;
  const initials = familyInitials(name);
  const coverImage = useImage(cover?.url);
  const overCover = cover != null && coverImage.shown;
  const floatingAction = heroAction ? <div className="absolute top-3 right-4 z-10">{heroAction}</div> : null;

  if (variant === "compact") {
    return (
      <div className="relative">
        {overCover && floatingAction}
        {overCover && (
          <img
            src={cover.url}
            alt=""
            referrerPolicy="no-referrer"
            onError={coverImage.onError}
            className="block h-30 w-full object-cover"
          />
        )}
        <header className="flex items-center gap-3 border-b border-line bg-paper px-6 py-4">
          <HeroLogo
            logo={logo}
            initials={initials}
            className={
              overCover
                ? "relative -mt-12 h-18 w-18 shrink-0 self-start border-4 border-paper shadow-md"
                : "h-14 w-14 shrink-0"
            }
            initialsClassName="bg-primary font-serif text-lg font-semibold text-on-primary"
          />
          <div className="min-w-0 flex-1">
            <h1 className="line-clamp-2 font-serif text-xl leading-tight font-bold wrap-break-word text-ink">{name}</h1>
            <p className="truncate text-[12.5px] text-ink-soft">domena.pl/{slug}</p>
          </div>
          {!overCover && heroAction}
          <ShareButton
            slug={slug}
            name={name}
            label="Udostępnij"
            iconOnly
            className="flex min-h-[44px] w-11 shrink-0 items-center justify-center rounded-full bg-primary-soft text-primary-fg focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-focus-ring"
          />
        </header>
      </div>
    );
  }

  if (variant === "centered") {
    // The LINKS page is the primary color; the cover fades into it below the name.
    const textColor = overCover ? "text-on-ink" : "text-on-primary";
    return (
      <header className="relative overflow-hidden">
        {floatingAction}
        {overCover && (
          <>
            <img
              src={cover.url}
              alt=""
              referrerPolicy="no-referrer"
              onError={coverImage.onError}
              className="absolute inset-0 h-full w-full object-cover"
            />
            <span aria-hidden="true" className={CENTERED_SCRIM} />
          </>
        )}
        <div
          className={`relative flex flex-col items-center px-6 text-center ${overCover ? "min-h-80 justify-end pt-16 pb-20" : "pt-12 pb-8"}`}
        >
          <HeroLogo
            logo={logo}
            initials={initials}
            className={`mb-4 h-24 w-24 border-4 ${overCover ? "border-on-ink" : "border-on-primary"}`}
            initialsClassName="bg-paper font-serif text-3xl font-bold text-primary-fg"
          />
          <h1 className={`font-serif text-3xl font-bold tracking-tight ${textColor}`}>{name}</h1>
          <p className={`mt-1 text-sm ${textColor}`}>domena.pl/{slug}</p>
        </div>
      </header>
    );
  }

  // Over a photo the palette's on-primary may be dark, so the text and the
  // logo ring switch to the fixed light token over the strong scrim.
  const textColor = overCover ? "text-on-ink" : "text-on-primary";
  const ringColor = overCover ? "border-on-ink" : "border-on-primary";

  return (
    <header
      className={`relative flex flex-col justify-end overflow-hidden rounded-b-[34px] bg-primary ${overCover ? "min-h-75" : ""}`}
    >
      {floatingAction}
      {overCover && (
        <>
          <img
            src={cover.url}
            alt=""
            referrerPolicy="no-referrer"
            onError={coverImage.onError}
            className="absolute inset-0 h-full w-full object-cover"
          />
          <span aria-hidden="true" className={COVER_SCRIM} />
        </>
      )}
      <div className="relative flex flex-col gap-4 px-6 pt-10 pb-8">
        <HeroLogo
          logo={logo}
          initials={initials}
          className={`h-20 w-20 border-4 ${ringColor}`}
          initialsClassName="bg-primary font-serif text-2xl font-bold text-on-primary"
        />
        <div>
          <h1 className={`font-serif text-4xl leading-tight font-bold tracking-tight ${textColor}`}>{name}</h1>
          <p className={`mt-1 text-sm ${textColor}`}>domena.pl/{slug}</p>
        </div>
      </div>
    </header>
  );
}

import { useRef, type KeyboardEvent } from "react";
import { isRecommended, LAYOUT_REGISTRY } from "../layouts/registry";
import type { OrganizerPageData } from "../layouts/types";
import { nextIndex } from "./rovingIndex";

const LAYOUTS = Object.values(LAYOUT_REGISTRY);

interface LayoutTabProps {
  value: string;
  data: OrganizerPageData;
  onSelect: (key: string) => void;
}

/** The layout cards, as a radio group in registry order. */
export function LayoutTab({ value, data, onSelect }: LayoutTabProps) {
  const cardRefs = useRef<(HTMLButtonElement | null)[]>([]);

  function handleKeyDown(event: KeyboardEvent<HTMLButtonElement>, index: number) {
    const next = nextIndex(event.key, index, LAYOUTS.length);
    if (next === null) return;
    event.preventDefault();
    onSelect(LAYOUTS[next].key);
    cardRefs.current[next]?.focus();
  }

  return (
    <div role="radiogroup" aria-label="Układ strony" className="grid grid-cols-2 gap-2.5">
      {LAYOUTS.map((layout, index) => {
        const selected = layout.key === value;
        const recommended = isRecommended(layout, data);
        const labelId = `editor-layout-${layout.key}-label`;
        const badgeId = `editor-layout-${layout.key}-badge`;
        const descriptionId = `editor-layout-${layout.key}-description`;
        return (
          <button
            key={layout.key}
            ref={(element) => {
              cardRefs.current[index] = element;
            }}
            type="button"
            role="radio"
            aria-checked={selected}
            aria-labelledby={labelId}
            aria-describedby={recommended ? `${badgeId} ${descriptionId}` : descriptionId}
            tabIndex={selected ? 0 : -1}
            onClick={() => onSelect(layout.key)}
            onKeyDown={(event) => handleKeyDown(event, index)}
            className={`relative flex min-h-[44px] flex-col gap-1.5 rounded-2xl border-2 p-2.5 text-left font-sans focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-focus-ring ${
              selected ? "border-primary bg-primary-soft" : "border-line bg-paper"
            }`}
          >
            <img src={layout.thumbnail.src} alt={layout.thumbnail.alt} className="w-full rounded-xl" />
            <span id={labelId} className="text-sm font-bold text-ink">
              {layout.label}
            </span>
            {recommended && (
              <span
                id={badgeId}
                className="self-start rounded-full bg-accent-soft px-2 py-0.5 text-[11px] font-extrabold text-accent-fg"
              >
                Polecany
              </span>
            )}
            <span id={descriptionId} className="text-[12px] text-ink-soft">
              {layout.description}
            </span>
            {selected && (
              <span
                aria-hidden="true"
                className="absolute right-2 top-2 flex h-6 w-6 items-center justify-center rounded-full bg-primary text-xs font-extrabold text-on-primary"
              >
                ✓
              </span>
            )}
          </button>
        );
      })}
    </div>
  );
}

import { createContext, useCallback, useContext, useEffect, useMemo, useState } from "react";
import type { ReactNode } from "react";
import type { PluginResponse } from "../../api/plugins";
import { getPlugins } from "../../api/plugins";
import { createMessageHandler } from "./PluginMessageHandler";
import { MENU_MAIN, PRODUCT_DETAIL_INFO, PRODUCT_DETAIL_TABS, PRODUCT_LIST_FILTERS } from "../extensionPoints";
import { iframeRegistry } from "./iframeRegistry";
import type { ResolvedExtensionPoint } from "../resolveExtensionPoints";
import { resolveExtensionPoints } from "../resolveExtensionPoints";

interface PluginContextValue {
  plugins: PluginResponse[];
  loading: boolean;
  error: string | null;
  refetch: () => Promise<void>;
  getMenuItems: () => ResolvedExtensionPoint[];
  getProductDetailTabs: (pluginId?: string) => ResolvedExtensionPoint[];
  getProductListFilters: () => ResolvedExtensionPoint[];
  getProductDetailInfo: () => ResolvedExtensionPoint[];
}

const PluginContext = createContext<PluginContextValue | null>(null);

export function PluginProvider({ children }: { children: ReactNode }) {
  const [plugins, setPlugins] = useState<PluginResponse[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  const refetch = useCallback(async () => {
    setLoading(true);
    setError(null);
    try {
      const data = await getPlugins();
      setPlugins(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : "Failed to load plugins");
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    void refetch();
  }, [refetch]);

  // Install the global postMessage handler once
  useEffect(() => {
    const handler = createMessageHandler(iframeRegistry);
    window.addEventListener("message", handler);
    return () => window.removeEventListener("message", handler);
  }, []);

  const getMenuItems = useCallback(
    () => resolveExtensionPoints(plugins, MENU_MAIN),
    [plugins],
  );

  const getProductDetailTabs = useCallback(
    (pluginId?: string) => resolveExtensionPoints(plugins, PRODUCT_DETAIL_TABS, pluginId),
    [plugins],
  );

  const getProductListFilters = useCallback(
    () => resolveExtensionPoints(plugins, PRODUCT_LIST_FILTERS),
    [plugins],
  );

  const getProductDetailInfo = useCallback(
    () => resolveExtensionPoints(plugins, PRODUCT_DETAIL_INFO),
    [plugins],
  );

  const value = useMemo<PluginContextValue>(
    () => ({ plugins, loading, error, refetch, getMenuItems, getProductDetailTabs, getProductListFilters, getProductDetailInfo }),
    [plugins, loading, error, refetch, getMenuItems, getProductDetailTabs, getProductListFilters, getProductDetailInfo],
  );

  return <PluginContext value={value}>{children}</PluginContext>;
}

export function usePluginContext(): PluginContextValue {
  const context = useContext(PluginContext);
  if (!context) {
    throw new Error("usePluginContext must be used within a PluginProvider");
  }
  return context;
}

import { useEffect, useRef } from "react";
import type { ExtensionPointType } from "../extensionPoints";
import { ADD_EVENT, MENU_MAIN, PRODUCT_DETAIL_INFO, PRODUCT_DETAIL_TABS, PRODUCT_LIST_FILTERS } from "../extensionPoints";
import { iframeRegistry } from "../host/iframeRegistry";

interface PluginFrameProps {
  pluginId: string;
  pluginName: string;
  pluginUrl: string;
  contextType: ExtensionPointType;
  contextData?: Record<string, unknown>;
  path: string;
  style?: React.CSSProperties;
  title?: string;
}

const CONTEXT_TYPE_PREFIX: Record<ExtensionPointType, string> = {
  [MENU_MAIN]: "RENDER",
  [PRODUCT_DETAIL_TABS]: "PRODUCT_DETAIL",
  [PRODUCT_LIST_FILTERS]: "FILTER",
  [PRODUCT_DETAIL_INFO]: "PRODUCT_DETAIL",
  [ADD_EVENT]: "RENDER",
};

function buildContextString(props: PluginFrameProps): string {
  const prefix = CONTEXT_TYPE_PREFIX[props.contextType] ?? "RENDER";
  const contextPayload: Record<string, unknown> = {
    pluginId: props.pluginId,
    pluginName: props.pluginName,
    hostOrigin: window.location.origin,
    ...props.contextData,
  };
  return `${prefix}${JSON.stringify(contextPayload)}`;
}

const SANDBOX = "allow-scripts allow-same-origin allow-forms allow-popups allow-modals allow-downloads";

export function PluginFrame(props: PluginFrameProps) {
  const iframeRef = useRef<HTMLIFrameElement>(null);
  const initializedRef = useRef(false);

  useEffect(() => {
    const iframe = iframeRef.current;
    if (!iframe) return;

    // Only set iframe src once to avoid reloading the plugin
    if (!initializedRef.current) {
      initializedRef.current = true;

      // Set name before src so the plugin can read context on load
      const contextString = buildContextString(props);
      iframe.name = contextString;

      // Also pass context as URL hash fragment (fallback for when window.name is cleared by dev servers)
      const src = new URL(props.path, props.pluginUrl);
      src.hash = encodeURIComponent(contextString);
      iframe.src = src.toString();
    }

    // Always register — must survive StrictMode's cleanup/re-run cycle
    iframeRegistry.register(iframe, {
      pluginId: props.pluginId,
      pluginUrl: props.pluginUrl,
    });

    return () => {
      iframeRegistry.unregister(iframe);
    };
  }, [props.pluginId, props.pluginName, props.pluginUrl, props.contextType, props.path, props.contextData]);

  return (
    <iframe
      ref={iframeRef}
      sandbox={SANDBOX}
      style={{ border: "none", width: "100%", height: "100%", ...props.style }}
      title={props.title ?? `Plugin: ${props.pluginName}`}
    />
  );
}

